import {RevisionRequests} from './revision-requests.mjs?v=requests1';
import {mountPlanAudio} from './plan-audio.mjs?v=sync5';
import {damageSummary,damageDetails} from './damage-display.mjs?v=damage18';
import {RUNES,valid,describe} from './combo-design.mjs?v=bolt17';
import {mountAtlasPreview} from './atlas-preview.mjs?v=click-timing-1';
const $=id=>document.getElementById(id),ids=Object.keys(RUNES);let seq=valid(location.hash.slice(1))?location.hash.slice(1):'qqw',branch=seq.slice(0,2),dispose=()=>{},disposeSound=()=>{};
const requests=new RevisionRequests();let disposeRequest=()=>{};
const recipe=s=>[...s].map(k=>RUNES[k].name).join(' → ');
const icons=s=>[...s].map(k=>`<span class="rune-icon" style="--rune:${RUNES[k].color}" title="${RUNES[k].name}">${RUNES[k].icon}</span>`).join('<i>＋</i>');
function button(s){const d=describe(s);return `<button data-seq="${s}" class="node ${seq===s?'selected':''} ${seq.startsWith(s)?'path':''}" aria-pressed="${seq===s}"><span class="icon-formula">${icons(s)}</span><b>${d.name}</b><small>${recipe(s)}</small><small class="damage-label">${damageSummary(s)}</small></button>`;}
function render(){const base=seq[0],d=describe(seq);if(branch.length!==2||branch[0]!==base)branch=base+base;if(seq.length>1)branch=seq.slice(0,2);document.documentElement.style.setProperty('--accent',d.color);
$('bases').innerHTML=ids.map(k=>`<button class="base-rune" data-seq="${k}" aria-pressed="${base===k}"><span class="rune-icon" style="--rune:${RUNES[k].color}">${RUNES[k].icon}</span><span><b>${RUNES[k].name}</b><small>1륜</small></span></button>`).join('');
const pool=$('repeat').checked?[...new Set(seq)]:ids;$('treeTitle').textContent=RUNES[base].name+'에서 시작';$('root').innerHTML=button(base);$('pairs').innerHTML=pool.map(k=>button(base+k)).join('');$('triples').innerHTML=pool.map(k=>button(branch+k)).join('');
dispose();disposeSound();disposeRequest();$('detail').innerHTML=`<span class="eyebrow">${seq.length===1?'1륜':seq.length+'중 2륜'} · 조합 마법</span><h2>${d.name}</h2><div class="icon-formula">${icons(seq)}</div><p>${recipe(seq)}</p>${damageDetails(seq)}<div id="atlasPreview"></div><div id="planSound"></div><section id="revisionRequest" class="revision-request"></section><div class="dual-role"><strong>${RUNES[base].name}의 두 역할</strong><p><span>무엇을</span>${RUNES[base].body}을 만듭니다</p><p><span>어떻게 한다</span>${RUNES[base].action}</p></div><ol>${d.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="notice">${d.balance}</p><button id="reverse">순서 뒤집어 비교</button><button id="share">조합 링크 복사</button><p id="status" role="status"></p>`;
// Use the model's generated first sentence for the correct Korean object particle.
$('detail').querySelector('.dual-role p').innerHTML='<span>무엇을</span>'+RUNES[base].body;
disposeRequest=requests.mount($('revisionRequest'),seq);const previewAudio=mountPlanAudio($('planSound'),seq);disposeSound=()=>previewAudio.dispose();dispose=mountAtlasPreview($('atlasPreview'),seq,previewAudio);$('reverse').onclick=()=>select([...seq].reverse().join(''));$('share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('status').textContent='링크를 복사했습니다.'}catch{$('status').textContent='주소창의 링크를 복사해 주세요.'}};renderRequests();requestAnimationFrame(drawConnections);}
function drawConnections(){const tree=$('tree'),svg=$('connections'),r=tree.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${tree.clientWidth} ${tree.scrollHeight}`);svg.style.height=tree.scrollHeight+'px';const paths=[];function link(a,b,on){if(!a||!b)return;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),x=ar.right-r.left,y=ar.top+ar.height/2-r.top,u=br.left-r.left,v=br.top+br.height/2-r.top,m=(x+u)/2;paths.push(`<path class="${on?'active':''}" d="M ${x} ${y} C ${m} ${y},${m} ${v},${u} ${v}"/>`);}const root=$('root').firstElementChild;for(const b of $('pairs').children)link(root,b,b.dataset.seq===branch);const selected=[...$('pairs').children].find(b=>b.dataset.seq===branch);for(const b of $('triples').children)link(selected,b,b.dataset.seq===seq);svg.innerHTML=paths.join('');}
function select(s){if(!valid(s))return;seq=s;history.replaceState(null,'','#'+seq);render();}document.addEventListener('click',e=>{const b=e.target.closest('[data-seq]');if(b)select(b.dataset.seq)});$('repeat').onchange=render;window.addEventListener('hashchange',()=>{if(valid(location.hash.slice(1))){seq=location.hash.slice(1);render()}});new ResizeObserver(()=>requestAnimationFrame(drawConnections)).observe($('tree'));window.addEventListener('pagehide',()=>dispose());render();

function renderRequests(){
 document.querySelectorAll('.node[data-seq]').forEach(node=>{let badge=node.querySelector('.request-badge');const exists=!!requests.items.get(node.dataset.seq)?.text;if(exists&&!badge){badge=document.createElement('small');badge.className='request-badge';badge.textContent='수정 요청 있음';node.append(badge);}else if(!exists&&badge)badge.remove();});
 const list=document.getElementById('requestList');list.replaceChildren();const entries=[...requests.items.values()].filter(x=>x.text).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));document.getElementById('requestTotal').textContent='저장한 수정 요청 '+entries.length+'개';
 if(!entries.length){const text=document.createElement('p');text.textContent=requests.error||'저장한 수정 요청이 없습니다. 조합을 선택해 요청을 작성하세요.';list.append(text);}
 for(const item of entries){const button=document.createElement('button');button.type='button';button.textContent=recipe(item.sequence)+' · '+item.text.slice(0,70)+(item.text.length>70?'…':'');button.onclick=()=>{select(item.sequence);document.getElementById('revisionRequest').scrollIntoView({behavior:'smooth',block:'center'});};list.append(button);}
 const info=document.getElementById('requestNotebook');info.textContent=requests.notebook?'보관함 번호: '+requests.notebook:'';
}
requests.listeners.add(renderRequests);void requests.load();
